Array.from(employeeGroups.values()).map((employeeRows: any[], index: number) => {
        const first = employeeRows[0] || {};
        const employeeHours = employeeRows.reduce((sum: number, row: any) => sum + num(row.totalHours), 0);
        const details = employeeRows
            .sort((a: any, b: any) => String(a.clockInAt || '').localeCompare(String(b.clockInAt || '')))
            .map((row: any) => {
                const label = labelStatus(row.status);
                const technicalDay = ['ABSENT', 'LEAVE', 'REST_DAY'].includes(String(row.status || '').toUpperCase());
                return `
                    <tr class="day-row">
                        <td></td>
                        <td>${htmlEscape(datePart(row.clockInAt))}</td>
                        <td>${htmlEscape(technicalDay ? '-' : timePart(row.clockInAt))}</td>
                        <td>${htmlEscape(timePart(row.clockOutAt))}</td>
                        <td class="center strong">${num(row.totalHours).toFixed(2)}</td>
                        <td class="center late">${num(row.lateMinutes)}</td>
                        <td class="center early">${num(row.earlyLeaveMinutes)}</td>
                        <td class="center overtime">${num(row.overtimeMinutes)}</td>
                        <td><span class="pill ${statusClass(label)}">${htmlEscape(label)}</span></td>
                    </tr>
                `;
            }).join('');
        return `
            <tr class="employee-row">
                <td class="center">${index + 1}</td>
                <td colspan="3"><div class="employee-name">${htmlEscape(first.employeeName || first.employeeId || '-')}</div><div class="employee-meta">${htmlEscape(first.employeeCode || first.employeeId || '-')} · ${htmlEscape(first.branchName || first.branchId || '-')}</div></td>
                <td class="center strong">${employeeHours.toFixed(2)}</td>
                <td colspan="2" class="center">${text.completed}: ${employeeRows.filter((row: any) => labelStatus(row.status) === text.completed).length}</td>
                <td colspan="2" class="center">${text.days}: ${employeeRows.length}</td>
            </tr>
            ${details}
        `;
    }).join

(async () => {
            await pool.query(`
                IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_orders_branch_status_created' AND object_id = OBJECT_ID('dbo.orders'))
                    CREATE INDEX IX_orders_branch_status_created ON dbo.orders(branch_id, status, created_at) INCLUDE (total);
            `);
            // Covering index for dashboard/report range scans: branch + created
            // range with all aggregated money columns included, so the 15-leg
            // fan-out never does key lookups. Supersedes idx_orders_branch_date
            // (same key prefix without INCLUDEs) which is dropped to avoid a
            // redundant twin.
            await pool.query(`
                IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_orders_branch_created_cover' AND object_id = OBJECT_ID('dbo.orders'))
                    CREATE INDEX IX_orders_branch_created_cover ON dbo.orders(branch_id, created_at) INCLUDE (status, total, subtotal, discount, tax, business_date);
            `);
            await pool.query(`
                IF EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'idx_orders_branch_date' AND object_id = OBJECT_ID('dbo.orders'))
                AND EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_orders_branch_created_cover' AND object_id = OBJECT_ID('dbo.orders'))
                    DROP INDEX idx_orders_branch_date ON dbo.orders;
            `);
            await pool.query(`
                IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_audit_logs_createdAt' AND object_id = OBJECT_ID('dbo.audit_logs'))
                    CREATE INDEX IX_audit_logs_createdAt ON dbo.audit_logs(created_at DESC);
            `);
            ensured = true;
        })().catch

